import { CATEGORY_LABEL } from "@/lib/vessels/types";
import type { DocumentRow, DemoState } from "../types";

/**
 * Bytes for demo downloads. Files uploaded in this tab are kept in memory and returned as is;
 * everything else (seeded documents, uploads from an earlier visit) gets a small generated file.
 */

const uploaded = new Map<string, Blob>();

export function keepUpload(id: string, file: Blob): void {
  uploaded.set(id, file);
}

export function forgetUpload(id: string): void {
  uploaded.delete(id);
}

/** PDF strings: printable ASCII only, with (, ) and \ escaped */
function pdfText(s: string): string {
  return s
    .normalize("NFD")
    .replace(/[^\x20-\x7e]/g, "")
    .replace(/([\\()])/g, "\\$1");
}

/** Minimal single-page PDF 1.4 (Helvetica) with correct xref offsets */
function buildPdf(title: string, lines: string[]): Blob {
  const content = [
    "BT /F1 18 Tf 56 780 Td (" + pdfText(title) + ") Tj ET",
    "BT /F1 10 Tf 56 756 Td 14 TL",
    ...lines.map((l) => "(" + pdfText(l) + ") '"),
    "ET",
  ].join("\n");
  const objects = [
    "<< /Type /Catalog /Pages 2 0 R >>",
    "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
    "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>",
    `<< /Length ${content.length} >>\nstream\n${content}\nendstream`,
    "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
  ];
  let out = "%PDF-1.4\n";
  const offsets: number[] = [];
  objects.forEach((body, i) => {
    offsets.push(out.length);
    out += `${i + 1} 0 obj\n${body}\nendobj\n`;
  });
  const xref = out.length;
  out += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`;
  out += offsets.map((o) => `${String(o).padStart(10, "0")} 00000 n \n`).join("");
  out += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`;
  return new Blob([out], { type: "application/pdf" });
}

function describe(doc: DocumentRow, state: DemoState): string[] {
  const vessel = doc.vesselId ? state.vessels.find((v) => v.id === doc.vesselId)?.name : null;
  const uploader = state.users.find((u) => u.id === doc.uploadedById);
  return [
    "Avalon Shipping SRL - demo document",
    "",
    `Category: ${CATEGORY_LABEL[doc.category]}`,
    `Vessel: ${vessel ?? "-"}`,
    `File: ${doc.originalName}`,
    `Uploaded by: ${uploader ? `${uploader.firstName} ${uploader.lastName}` : "-"}`,
    `Uploaded at: ${new Date(doc.createdAt).toUTCString()}`,
    `Notes: ${doc.notes ?? "-"}`,
    "",
    "This file was generated by the demo mode of the operations portal.",
    "It contains no real data.",
  ];
}

export function documentBlob(doc: DocumentRow, state: DemoState): Blob {
  const kept = uploaded.get(doc.id);
  if (kept) return kept;
  const lines = describe(doc, state);
  if (doc.mimeType === "application/pdf") return buildPdf(doc.title, lines);
  if (doc.mimeType === "text/csv") {
    return new Blob([`field,value\n${lines.filter(Boolean).map((l) => `"${l.replace(/"/g, '""')}"`).join("\n")}\n`], { type: "text/csv" });
  }
  return new Blob([`${doc.title}\n\n${lines.join("\n")}\n`], { type: "text/plain" });
}
